"""Skill catalog types and loader.

The catalog is the top-level registry of all skills available to the engine.

**Primary layout — ``skill.md`` (required)::

    <snapshot_dir>/skills/<skill_id>/
        skill.md        — YAML frontmatter + Markdown prose (compiled by
                          :func:`~rasa.mantle.skills.markdown_skill_compiler.compile_markdown_skill`)
        memory.yml      — SkillMemoryContract  (optional)
        responses.yml   — per-skill ResponseRegistry (optional)

Every skill directory must contain ``skill.md``.

The runtime catalog stores :class:`~rasa.mantle.skills.skill.Skill` with a
document-ordered ``body``. Defaults are merged first; project skills override
on duplicate IDs.
"""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING, Any, Mapping, NamedTuple, Optional, Sequence

import structlog
import yaml  # type: ignore[import-untyped]
from pydantic import BaseModel, ConfigDict, Field, field_validator

from rasa.exceptions import ValidationError
from rasa.mantle.memory.schema import SkillMemoryContract
from rasa.mantle.skills.conditions import Condition, GatedTool
from rasa.mantle.skills.logic import step_complete_when_from_spec
from rasa.mantle.skills.prose_scoping import ProseSegment
from rasa.mantle.skills.skill import (
    ORDERED_BLOCK_TARGET_ID_SEPARATOR,
    OrderedBlock,
    ProseBlock,
    Skill,
    find_step_by_id,
    format_ordered_block_target_id,
    format_skill_target_id,
)
from rasa.mantle.skills.steps import (
    AutonomousStep,
    CallStep,
    CollectStep,
    LinkStep,
    Step,
    parse_step,
)
from rasa.shared.core.flows.steps.constants import END_STEP

if TYPE_CHECKING:
    from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
        OrderedBlockStackFrame,
        SkillStackFrame,
    )

structlogger = structlog.get_logger()

# Step ID used for the virtual AutonomousStep when resolving a skill frame.
_SYNTHETIC_STEP_ID = "autonomous"


# ---------------------------------------------------------------------------
# SkillCatalog helpers
# ---------------------------------------------------------------------------


def build_collect_owned_entries(
    skills: dict[str, Skill],
) -> dict[str, frozenset[str]]:
    """Return memory entry names owned by a ``collect`` step in each skill.

    Computed once at catalog load so discovery and correction can reuse the
    index without re-walking every block on each post-turn call.
    """
    owned: dict[str, set[str]] = {}
    for skill_id, skill in skills.items():
        entries: set[str] = set()
        for block in ordered_blocks_in_body(skill):
            for step in block.steps:
                if isinstance(step, CollectStep):
                    entries.add(step.collect)
        if entries:
            owned[skill_id] = entries
    return {skill_id: frozenset(entries) for skill_id, entries in owned.items()}


def skill_settable_entry_names(
    skill: Skill,
    *,
    collect_owned: frozenset[str],
) -> frozenset[str]:
    """Return entry names the LLM may set via ``set_fields`` for *skill*.

    The settable set is the union of fields flagged ``llm_settable: true`` and
    fields owned by a collect step.

    This is **LLM / this-turn settable** for ``set_fields`` — not the set of
    keys a static ``set:`` button may write. Button taps are engine writes; see
    :func:`~rasa.mantle.content.static_buttons.button_writable_memory_keys_for_skill`.
    """
    llm_settable = {
        name
        for name, field in skill.memory.definition.all_fields().items()
        if field.llm_settable
    }
    return frozenset(llm_settable | set(collect_owned))


def collect_step_descriptions(skill: Skill) -> dict[str, str | None]:
    """Map collect entry names to their step-level descriptions.

    When several collect steps fill the same field, the later step in document
    order wins, including when that later description is empty.
    """
    descriptions: dict[str, str | None] = {}
    for block in ordered_blocks_in_body(skill):
        for step in block.steps:
            if isinstance(step, CollectStep):
                descriptions[step.collect] = step.description
    return descriptions


def nonempty_description(text: str | None) -> str | None:
    """Return *text* when it contains non-whitespace, else ``None``.

    Padding on a real description is kept. ``None``, ``""``, and whitespace-only
    text are missing.
    """
    if text is None or not text.strip():
        return None
    return text


def blank_winning_collect_step_id(skill: Skill, field_name: str) -> str | None:
    """Return the last collect step id when it drops an earlier description.

    The last collect step for ``field_name`` wins, including when its
    description is blank. When that step has no non-whitespace description and
    an earlier collect step for the same field did, return the last step's id.
    Otherwise return ``None``.
    """
    steps = [
        step
        for block in ordered_blocks_in_body(skill)
        for step in block.steps
        if isinstance(step, CollectStep) and step.collect == field_name
    ]
    if len(steps) < 2:
        return None
    if nonempty_description(steps[-1].description) is not None:
        return None
    if any(nonempty_description(step.description) is not None for step in steps[:-1]):
        return steps[-1].id
    return None


def resolved_memory_field_description(
    skill: Skill,
    field_name: str,
    *,
    collect_descriptions: Mapping[str, str | None] | None = None,
) -> str | None:
    """Return the description the model sees for one memory field.

    The last collect step's description wins when it has non-whitespace text.
    Otherwise the memory-field description is used. An earlier collect step's
    text is not used once a later collect step for the same field exists.

    Args:
        skill: Skill that declares the field.
        field_name: Memory entry name.
        collect_descriptions: Collect-step descriptions for ``skill``, already
            walked once. When omitted, they are collected from ``skill``.

    Returns:
        The description the model sees, or ``None`` when neither source has
        non-whitespace text.
    """
    descriptions = (
        collect_step_descriptions(skill)
        if collect_descriptions is None
        else collect_descriptions
    )
    winning = nonempty_description(descriptions.get(field_name))
    if winning is not None:
        return winning
    field = skill.memory.definition.all_fields().get(field_name)
    if field is None:
        return None
    return nonempty_description(field.description)


def ordered_blocks_in_body(skill: Skill) -> list[OrderedBlock]:
    """Return ordered blocks from *skill* ``body`` in document order."""
    return [block for block in skill.body if isinstance(block, OrderedBlock)]


def prose_segments_from_body(skill: Skill) -> list[ProseSegment]:
    """Flatten ``ProseBlock`` segments from *skill* ``body`` in document order."""
    segments: list[ProseSegment] = []
    for block in skill.body:
        if isinstance(block, ProseBlock):
            segments.extend(block.segments)
    return segments


def prose_ordered_block_target_ids(skill: Skill) -> list[str]:
    """Compiled ids of ordered blocks the skill prose names with ``@block``."""
    from rasa.mantle.skills.markdown_skill_compiler import (
        collect_prose_block_references,
    )

    local_block_ids = {block.block_id for block in ordered_blocks_in_body(skill)}
    target_ids: list[str] = []
    seen: set[str] = set()
    for segment in prose_segments_from_body(skill):
        for block_id in collect_prose_block_references(segment.text):
            if block_id not in local_block_ids:
                continue
            target_id = format_ordered_block_target_id(skill.id, block_id)
            if target_id in seen:
                continue
            seen.add(target_id)
            target_ids.append(target_id)
    return target_ids


def llm_facing_instruction_texts(skill: Skill) -> list[str]:
    """Return LLM-facing instruction strings (not ``if:`` conditions).

    Includes outer prose segment bodies and non-empty
    :class:`~rasa.mantle.skills.steps.AutonomousStep` ``instructions``.
    """
    texts = [segment.text for segment in prose_segments_from_body(skill)]
    for target in iter_resolved_activation_targets(skill):
        for step in target.steps:
            if isinstance(step, AutonomousStep) and step.instructions:
                texts.append(step.instructions)
    return texts


def virtual_prose_step_for_skill(skill: Skill) -> AutonomousStep:
    """Return the virtual prose :class:`AutonomousStep` for a skill frame.

    Not stored in ``body``. Step-level ``complete_when`` follows the same rules
    as the markdown compiler's synthetic prose step.
    """
    return AutonomousStep(
        id=_SYNTHETIC_STEP_ID,
        instructions="",
        complete_when=step_complete_when_from_spec(skill.complete_when),
        next=END_STEP,
    )


# ---------------------------------------------------------------------------
# ResolvedActivationTarget — body-backed projection for validation / telemetry
# ---------------------------------------------------------------------------


class ResolvedActivationTarget(NamedTuple):
    """Read-time projection of one activate ``target_id`` from ``Skill.body``.

    Not an authored type: walkers (validation, telemetry, prompts, executor)
    resolve a target into ``target_id`` / ``steps`` / ``tools`` /
    ``complete_when`` / ``routable``. Prose uses
    :func:`virtual_prose_step_for_skill` (not stored in ``body``); ordered
    blocks copy fields from :class:`OrderedBlock`.
    """

    target_id: str
    steps: list[Step]
    tools: list[GatedTool]
    complete_when: Condition | None = None
    routable: bool = True
    file_path: str | None = None
    description: str | None = None

    def step_by_id(self, step_id: str) -> Step | None:
        """Return the step with the given ID, or ``None`` if not found."""
        return find_step_by_id(self.steps, step_id)


def iter_resolved_activation_targets(skill: Skill) -> list[ResolvedActivationTarget]:
    """Return resolved body targets for validation and telemetry walkers."""
    targets: list[ResolvedActivationTarget] = []
    if skill_has_prose(skill):
        targets.append(
            ResolvedActivationTarget(
                target_id=format_skill_target_id(skill.id),
                steps=[virtual_prose_step_for_skill(skill)],
                tools=[],
                routable=True,
            )
        )
    for block in ordered_blocks_in_body(skill):
        targets.append(
            ResolvedActivationTarget(
                target_id=format_ordered_block_target_id(skill.id, block.block_id),
                steps=list(block.steps),
                tools=list(block.tools),
                complete_when=block.complete_when,
                routable=block.routable,
            )
        )
    return targets


def _coerce_skill_mapping(skills: Any) -> Any:
    """Normalize catalog ``skills`` values to :class:`Skill` instances."""
    if not isinstance(skills, dict):
        return skills
    coerced: dict[str, Any] = {}
    for skill_id, value in skills.items():
        if isinstance(value, Skill):
            coerced[skill_id] = value
        elif isinstance(value, dict):
            coerced[skill_id] = Skill.model_validate(value)
        else:
            coerced[skill_id] = value
    return coerced


class SkillCatalog(BaseModel):
    """Registry of all skills available at runtime."""

    model_config = ConfigDict(frozen=True)

    skills: dict[str, Skill] = Field(default_factory=dict)
    collect_owned_entries: dict[str, frozenset[str]] = Field(default_factory=dict)

    @field_validator("skills", mode="before")
    @classmethod
    def _coerce_skills(cls, value: Any) -> Any:
        """Validate/coerce mapping values into :class:`Skill`."""
        return _coerce_skill_mapping(value)

    def model_post_init(self, __context: Any) -> None:
        """Precompute collect-owned memory entries when not supplied explicitly."""
        if not self.collect_owned_entries:
            object.__setattr__(
                self,
                "collect_owned_entries",
                build_collect_owned_entries(self.skills),
            )

    def skill_by_id(self, skill_id: str) -> Skill | None:
        """Return the :class:`~rasa.mantle.skills.skill.Skill` for *skill_id*."""
        return self.skills.get(skill_id)

    def ordered_block_for_target_id(self, target_id: str) -> OrderedBlock | None:
        """Walk *skill* ``body`` for the ordered block addressed by *target_id*."""
        match = _compiled_match_for_target_id(self.skills, target_id)
        if match is None:
            return None
        _, block = match
        return block

    def has_activation_target(self, target_id: str) -> bool:
        """Return whether *target_id* resolves to a prose entry or ordered block."""
        return _compiled_match_for_target_id(self.skills, target_id) is not None

    def resolve_activation_target(
        self, target_id: str
    ) -> ResolvedActivationTarget | None:
        """Build a body-backed :class:`ResolvedActivationTarget` for *target_id*.

        Ordered blocks are projected from ``body``. Prose entries use the
        virtual autonomous step (not stored in ``body``). Prefer
        :meth:`ordered_block_for_target_id` / :func:`virtual_prose_step_for_skill`
        when callers only need one of those pieces.
        """
        match = _compiled_match_for_target_id(self.skills, target_id)
        if match is None:
            return None
        skill, block = match
        if block is not None:
            return ResolvedActivationTarget(
                target_id=format_ordered_block_target_id(skill.id, block.block_id),
                steps=list(block.steps),
                tools=list(block.tools),
                complete_when=block.complete_when,
                routable=block.routable,
            )
        return ResolvedActivationTarget(
            target_id=format_skill_target_id(skill.id),
            steps=[virtual_prose_step_for_skill(skill)],
            tools=[],
            routable=True,
        )

    def owning_skill_for_target_id(self, target_id: str) -> Skill | None:
        """Return the :class:`~rasa.mantle.skills.skill.Skill` that owns *target_id*.

        Compiled prose and ``{skill}__{block}`` addresses match exactly, including
        when *skill* itself contains ``__``. Skill ids with no matching compiled
        entry (empty body, call/link skill-id targets) fall back to catalog
        membership.
        """
        match = _compiled_match_for_target_id(self.skills, target_id)
        if match is not None:
            return match[0]
        return self.skills.get(target_id)

    def ordered_block_id_for_target(self, target_id: str) -> str | None:
        """Return the authored block id for *target_id*, or ``None`` for prose."""
        block = self.ordered_block_for_target_id(target_id)
        return block.block_id if block is not None else None

    def target_id_for_frame(
        self, frame: "SkillStackFrame | OrderedBlockStackFrame"
    ) -> str:
        """Return the compiled target id that currently executes *frame*.

        Skill frames map to the prose entry (``skill_id``). Ordered-block
        frames map to ``{skill_id}__{block_id}``.
        """
        return target_id_for_frame(frame)

    def referenced_callee_skill_id(
        self, target_id: str, parent_skill_id: str
    ) -> str | None:
        """Return callee skill id for a referenced activate *target_id*.

        Returns ``None`` when the target is intra-skill only.
        """
        target_skill = self.skills.get(target_id)
        if target_skill is not None:
            return target_skill.id if target_skill.id != parent_skill_id else None
        target_skill = self.owning_skill_for_target_id(target_id)
        if target_skill is not None and target_skill.id != parent_skill_id:
            return target_skill.id
        return None

    def is_referenced_skill_id(
        self, parent_skill_id: str, callee_skill_id: str
    ) -> bool:
        """Return whether *callee_skill_id* is in parent's ``referenced_skills``."""
        parent = self.skill_by_id(parent_skill_id)
        if parent is None:
            return False
        for target in parent.referenced_skills:
            if (
                self.referenced_callee_skill_id(target, parent_skill_id)
                == callee_skill_id
            ):
                return True
        return False

    def is_referenced_skill_target(self, parent_skill_id: str, target_id: str) -> bool:
        """Return whether *target_id* is a skill the parent delegates to.

        True when *target_id* is an entry in the parent's ``referenced_skills``,
        or the id that starts that skill. ``activate`` then keeps the parent
        and resumes it when the callee finishes.
        """
        parent = self.skill_by_id(parent_skill_id)
        if parent is None:
            return False
        callee_skill = self.owning_skill_for_target_id(target_id)
        if callee_skill is None or callee_skill.id == parent_skill_id:
            return False
        for target in parent.referenced_skills:
            callee_id = self.referenced_callee_skill_id(target, parent_skill_id)
            if callee_id is None:
                continue
            resolved = resolve_call_activation_target_id(self, target)
            if target_id in {resolved, callee_id}:
                return True
        return False

    def is_referenced_block_target(self, parent_skill_id: str, target_id: str) -> bool:
        """Return whether *target_id* is an intra-skill block on *parent*.

        True when *target_id* is listed in the parent's ``referenced_blocks``
        (from ``call:`` / ``link:`` / prose ``@block``). Used by
        ``activate`` to enter a same-skill ordered block without treating
        the switch as a digression ``INTERRUPT``.
        """
        parent = self.skill_by_id(parent_skill_id)
        if parent is None:
            return False
        return target_id in parent.referenced_blocks

    def get_startable_candidate_target_ids(
        self,
        memory_values: dict[str, Any],
        *,
        active_target_id: str | None = None,
        paused_block_ids: Sequence[str] = (),
    ) -> list[str]:
        """Return target ids for the ``activate`` enum this turn.

        Starts from :meth:`routable_skill_ids` (skill ids). When a skill is
        active:

        * Always omits the live top frame.
        * Omits the running skill id, except when the top is an internal
          block of a skill with prose. That exception lets
          ``activate(skill_id)`` return to prose. A blocks-only skill has
          no prose to return to, so its skill id stays omitted and the
          called block is not left behind.
        * While a skill with prose is active, appends ordered-block ids that
          prose names with ``@block``. A blocks-only skill does not add
          block ids. Same-skill ``call:`` and ``link:`` targets are not added
          unless they are already parked and listed in *paused_block_ids*.
        * Appends *paused_block_ids*: compiled ids of same-skill blocks the
          active-skill prompt tells the model to resume. Unparked ``call:``
          and ``link:`` targets stay out of the enum.
        """
        target_ids = list(self.routable_skill_ids(dict(memory_values)))
        if not active_target_id:
            return target_ids

        active_skill = self.owning_skill_for_target_id(active_target_id)
        excluded = {active_target_id}
        keep_skill_id_for_prose = (
            active_skill is not None
            and skill_has_prose(active_skill)
            and self.is_internal_target(active_target_id)
        )
        if active_skill is not None and not keep_skill_id_for_prose:
            excluded.add(format_skill_target_id(active_skill.id))
            for block in ordered_blocks_in_body(active_skill):
                if block.routable:
                    excluded.add(
                        format_ordered_block_target_id(active_skill.id, block.block_id)
                    )

        target_ids = [
            target_id for target_id in target_ids if target_id not in excluded
        ]
        prose_block_ids = (
            prose_ordered_block_target_ids(active_skill)
            if active_skill is not None and skill_has_prose(active_skill)
            else []
        )
        extra_block_ids = [*prose_block_ids, *paused_block_ids]
        if not extra_block_ids:
            return target_ids

        seen = set(target_ids)
        seen.add(active_target_id)
        for block_target_id in extra_block_ids:
            if block_target_id in seen:
                continue
            if not self.has_activation_target(block_target_id):
                continue
            seen.add(block_target_id)
            target_ids.append(block_target_id)
        return target_ids

    def import_tool_names(self, skill_id: str) -> frozenset[str]:
        """Return shared tool names listed under ``import_tools`` in ``skill.md``."""
        skill = self.skills.get(skill_id)
        if skill is None:
            return frozenset()
        return skill.import_tool_names

    def tool_constraint_names(self, skill_id: str) -> frozenset[str]:
        """Return tool names constrained for this skill.

        Includes ``tool_constraints`` frontmatter plus every tool listed under
        an ordered block's ``tools`` section (same gating semantics).
        """
        skill = self.skills.get(skill_id)
        if skill is None:
            return frozenset()
        names = set(skill.tool_constraint_names)
        for block in ordered_blocks_in_body(skill):
            names.update(gate.name for gate in block.tools)
        return frozenset(names)

    def declared_tool_names(self, skill_id: str) -> set[str]:
        """Return every tool name the skill declares (skill-level or any block).

        This is the skill-wide union across contexts — a name in this set may
        still be absent from :meth:`resolve_tool_gates` for a specific target
        (declared only on another same-skill block). Used by the tool loader to
        scope shared tools to declaring skills. Bare gate names originating only
        from MCP imports do not declare same-named shared tools — including when
        those bare names also appear in ``tool_constraints`` or ordered-block
        ``tools`` (constraints/gates, not shared-tool imports). Only a
        non-``mcp/`` ``import_tools`` entry allowlists a shared Python tool.
        """
        skill = self.skills.get(skill_id)
        if skill is None:
            return set()
        names = {gate.name for gate in skill.tools}
        for block in ordered_blocks_in_body(skill):
            names.update(gate.name for gate in block.tools)

        from rasa.mantle.tools.mcp_import_spec import try_parse_mcp_tool_import

        shared_imports = {
            name for name in skill.import_tool_names if not name.startswith("mcp/")
        }
        for import_reference in skill.import_tool_names:
            try:
                mcp_import = try_parse_mcp_tool_import(import_reference)
            except ValueError:
                # Malformed ``mcp/…`` entries are reported by import_tools
                # validation; skip them here so a sibling valid MCP import does
                # not turn that report into an uncaught traceback.
                continue
            if mcp_import is not None and mcp_import.tool_name not in shared_imports:
                names.discard(mcp_import.tool_name)
        return names

    def resolve_tool_gates(self, skill_id: str, target_id: str) -> list[GatedTool]:
        """Return the effective :class:`GatedTool` gate list for a skill/target.

        Block-level gates take priority; skill-level gates fill in any tools
        not already declared by the block.  When *target_id* is empty (autonomous
        skill), only the skill-level gates are returned.

        This is the single source of truth for gate resolution — used by both
        the LLM schema builder and the runtime dispatcher so the two stay in
        sync.
        """
        skill = self.skills.get(skill_id)
        skill_gates: list[GatedTool] = list(skill.tools) if skill is not None else []

        if not target_id:
            return skill_gates

        block = self.ordered_block_for_target_id(target_id)
        if block is None:
            # Prose entry or unknown target: skill-level gates only.
            return skill_gates

        block_gates: list[GatedTool] = list(block.tools)
        if not block.routable:
            return block_gates
        block_gate_names = {t.name for t in block_gates}
        return block_gates + [t for t in skill_gates if t.name not in block_gate_names]

    def effective_tool_gate(
        self, skill_id: str, target_id: str, tool_name: str
    ) -> GatedTool | None:
        """Return the gate governing *tool_name* for engine-driven tool runs.

        :meth:`resolve_tool_gates` hides skill-level ``tool_constraints`` while a
        non-routable inline block is active so the LLM schema does not expose
        parent skill tools mid-block. Engine-side consumers — ordered-block
        ``execute_tool`` steps and ``on_success`` / ``on_failure`` verbatim
        triggers — still have to honour those frontmatter gates.

        Prefer ``skill.tools`` first: markdown compilation merges ordered-block
        ``tools:`` entries into that list with skill ``tool_constraints`` winning,
        so a bare block name must not shadow ``requires_confirmation`` /
        ``on_success`` / ``on_failure``. Fall back to target-scoped gates only
        when the skill list has no match.
        """
        skill = self.skills.get(skill_id)
        if skill is not None:
            skill_gate = next(
                (gate for gate in skill.tools if gate.name == tool_name),
                None,
            )
            if skill_gate is not None:
                return skill_gate

        return next(
            (
                gate
                for gate in self.resolve_tool_gates(skill_id, target_id)
                if gate.name == tool_name
            ),
            None,
        )

    def routable_entries(self, memory_values: dict[str, Any]) -> dict[str, list[str]]:
        """Return ``{skill_id: [target_ids]}`` for skills the LLM may activate.

        Excludes engine-managed, disabled, and ``hidden`` skills. Every
        startable skill contributes its skill id. A blocks-only skill is
        startable only when it has exactly one entry block.
        """
        result: dict[str, list[str]] = {}
        for skill_id, skill in self.skills.items():
            if skill.engine_managed:
                continue
            if _is_excluded_from_routable_entries(skill):
                continue
            target_id = routable_target_id_for_skill(skill)
            if target_id is None and skill.body:
                continue
            result[skill_id] = [target_id] if target_id is not None else []
        return result

    def routable_skill_ids(
        self,
        memory_values: dict[str, Any],
    ) -> list[str]:
        """Return skill ids allowed for routing and ``activate`` this turn.

        Every startable skill contributes its skill id. Ordered-block ids are
        not included here. While a skill with prose is active,
        :meth:`get_startable_candidate_target_ids` adds block ids that prose
        names with ``@block``.
        """
        return [
            target_id
            for skill_target_ids in self.routable_entries(memory_values).values()
            for target_id in skill_target_ids
        ]

    def is_internal_target(self, target_id: str) -> bool:
        """Return ``True`` when *target_id* is an internal (non-routable) block."""
        block = self.ordered_block_for_target_id(target_id)
        return block is not None and not block.routable

    def is_inline_main(self, target_id: str) -> bool:
        """Return ``True`` when *target_id* is a routable main with inline blocks."""
        if self.is_internal_target(target_id):
            return False
        skill = self.owning_skill_for_target_id(target_id)
        if skill is None:
            return False
        return any(not block.routable for block in ordered_blocks_in_body(skill))

    def inline_internal_target_ids(self, target_id: str) -> list[str]:
        """Return every internal block target id in the same skill as *target_id*."""
        skill = self.owning_skill_for_target_id(target_id)
        if skill is None:
            return []
        return [
            format_ordered_block_target_id(skill.id, block.block_id)
            for block in ordered_blocks_in_body(skill)
            if not block.routable
        ]

    def is_inline_sub_target_activation(
        self,
        active_target_id: str | None,
        target_id: str,
    ) -> bool:
        """Whether ``activate(active → target)`` pushes a new inline block."""
        if active_target_id is None:
            return False
        if self.is_internal_target(target_id):
            return self.targets_share_skill(active_target_id, target_id)
        return False

    def targets_share_skill(self, target_id_a: str, target_id_b: str) -> bool:
        """Return ``True`` when both target IDs resolve to the same skill."""
        skill_a = self.owning_skill_for_target_id(target_id_a)
        skill_b = self.owning_skill_for_target_id(target_id_b)
        return skill_a is not None and skill_b is not None and skill_a.id == skill_b.id

    def is_same_inline_family(self, target_id_a: str, target_id_b: str) -> bool:
        """Return ``True`` when two targets belong to one inline family."""
        if not self.targets_share_skill(target_id_a, target_id_b):
            return False
        return self.is_internal_target(target_id_a) or self.is_internal_target(
            target_id_b
        )


# ---------------------------------------------------------------------------
# Compiled target id convention (prose vs ordered block)
# ---------------------------------------------------------------------------


def is_prose_target_id(skill_id: str, target_id: str) -> bool:
    """Return whether *target_id* is the prose entry for *skill_id*."""
    return target_id == format_skill_target_id(skill_id)


def skill_has_prose(skill: Skill) -> bool:
    """Return whether *skill* has a prose entry (any :class:`ProseBlock` in body)."""
    return any(isinstance(block, ProseBlock) for block in skill.body)


def _compiled_match_for_target_id(
    skills: dict[str, Skill], target_id: str
) -> tuple[Skill, OrderedBlock | None] | None:
    """Return the skill and optional block whose compiled activate id is *target_id*.

    Walks skills in catalog order. For each skill, the prose entry is compared
    before ordered blocks so a skill whose id contains ``__`` still matches
    its full compiled address.
    """
    for skill in skills.values():
        if skill_has_prose(skill) and format_skill_target_id(skill.id) == target_id:
            return skill, None
        for block in ordered_blocks_in_body(skill):
            if format_ordered_block_target_id(skill.id, block.block_id) == target_id:
                return skill, block
    return None


def target_id_for_frame(
    frame: "SkillStackFrame | OrderedBlockStackFrame",
) -> str:
    """Return the compiled target id that currently executes *frame*.

    Skill frames map to the prose entry whose id equals ``skill_id``.
    Ordered-block frames map to ``{skill_id}__{block_id}``.
    """
    from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
        OrderedBlockStackFrame,
    )

    if isinstance(frame, OrderedBlockStackFrame):
        return format_ordered_block_target_id(frame.skill_id, frame.block_id)
    return format_skill_target_id(frame.skill_id)


def is_ordered_block_target_id(skill_id: str, target_id: str) -> bool:
    """Return whether *target_id* is a compiled ordered block on *skill_id*."""
    return target_id.startswith(f"{skill_id}{ORDERED_BLOCK_TARGET_ID_SEPARATOR}")


def _call_or_link_target(step: Step) -> str | None:
    """Return the target of a ``call:`` or ``link:`` step."""
    if isinstance(step, CallStep):
        return step.call
    if isinstance(step, LinkStep):
        return step.link
    return None


def _local_ordered_block_id(
    raw: str, skill_id: str, local_block_ids: set[str]
) -> str | None:
    """Return the block id if *raw* is a block in this skill, else ``None``.

    *raw* is the block id or ``{skill_id}__{block_id}``.
    """
    if raw in local_block_ids:
        return raw
    prefix = f"{skill_id}{ORDERED_BLOCK_TARGET_ID_SEPARATOR}"
    if not raw.startswith(prefix):
        return None
    block_id = raw[len(prefix) :]
    if block_id not in local_block_ids:
        return None
    return block_id


def _same_skill_called_block_ids(skill: Skill) -> dict[str, list[str]]:
    """Map each block id to the same-skill blocks its steps call or link."""
    blocks = ordered_blocks_in_body(skill)
    local_block_ids = {block.block_id for block in blocks}
    edges: dict[str, list[str]] = {}
    for block in blocks:
        targets: list[str] = []
        for step in block.steps:
            raw = _call_or_link_target(step)
            if raw is None:
                continue
            block_id = _local_ordered_block_id(raw, skill.id, local_block_ids)
            if block_id is None or block_id in targets:
                continue
            targets.append(block_id)
        edges[block.block_id] = targets
    return edges


def entry_block_ids(skill: Skill) -> list[str]:
    """Return the entry ordered-block ids for a skill with no prose.

    An entry is an ordered block that no other block in this skill calls or
    links. Document order. Empty when every block is a ``call:`` or ``link:``
    target. A skill with prose enters at its skill id, not these blocks.
    """
    targeted = {
        target
        for targets in _same_skill_called_block_ids(skill).values()
        for target in targets
    }
    return [
        block.block_id
        for block in ordered_blocks_in_body(skill)
        if block.block_id not in targeted
    ]


def unreachable_ordered_block_ids(skill: Skill) -> list[str]:
    """Return ordered blocks the single entry cannot reach.

    A block is reachable through a same-skill ``call:`` or ``link:``. Empty
    when the skill does not have exactly one entry.
    """
    entries = entry_block_ids(skill)
    if len(entries) != 1:
        return []
    edges = _same_skill_called_block_ids(skill)
    reachable: set[str] = set()
    pending = [entries[0]]
    while pending:
        current = pending.pop()
        if current in reachable:
            continue
        reachable.add(current)
        pending.extend(edges.get(current, []))
    return [
        block.block_id
        for block in ordered_blocks_in_body(skill)
        if block.block_id not in reachable
    ]


def entry_target_id_for_skill(skill: Skill) -> str | None:
    """Return the target id that starts *skill* when activation names its skill id.

    Hybrid and autonomous skills enter the prose entry. A blocks-only skill
    enters its single entry block: the only ordered block that is not the
    target of a same-skill ``call:`` or ``link:``. The block id can be
    anything. Several entries, or none, return ``None``.
    """
    if not skill.body:
        return None
    if skill_has_prose(skill):
        return format_skill_target_id(skill.id)
    entries = entry_block_ids(skill)
    if len(entries) != 1:
        return None
    return format_ordered_block_target_id(skill.id, entries[0])


def resolve_call_activation_target_id(catalog: SkillCatalog, call_target: str) -> str:
    """Map a compiled :class:`CallStep` target to the target id to push at runtime."""
    return _resolve_activation_target_id(catalog, call_target)


def resolve_link_activation_target_id(catalog: SkillCatalog, link_target: str) -> str:
    """Map a compiled ``link:`` target to the target id to activate at runtime."""
    return _resolve_activation_target_id(catalog, link_target)


def _resolve_activation_target_id(catalog: SkillCatalog, target: str) -> str:
    """Shared runtime mapping from a compiled call/link target to a target id."""
    skill = catalog.owning_skill_for_target_id(target)
    if skill is not None and target == skill.id:
        return entry_target_id_for_skill(skill) or target
    return target


def ordered_block_ids_from_body(skill: Skill) -> set[str]:
    """Return ordered-block ids from *skill* ``body``."""
    return {block.block_id for block in ordered_blocks_in_body(skill)}


_INVALID_STEP_TARGET_CODE = "skill.markdown.invalid_step_target"


def _unknown_ordered_block_target_error(
    skill_id: str, block_id: str, *, reference_field: str
) -> ValidationError:
    return ValidationError(
        code=_INVALID_STEP_TARGET_CODE,
        event_info=(
            f"Unknown ordered block {block_id!r} on skill {skill_id!r}; "
            f"{reference_field}: must reference a block id defined in this skill."
        ),
    )


def _cross_skill_target_error(raw: str, *, reference_field: str) -> ValidationError:
    callee_skill_id = raw.split(ORDERED_BLOCK_TARGET_ID_SEPARATOR, 1)[0]
    return ValidationError(
        code=_INVALID_STEP_TARGET_CODE,
        event_info=(
            f"Cross-skill {reference_field} target {raw!r} must be a skill id, not a "
            f"compiled target id. Use the callee skill's id "
            f"(e.g. {callee_skill_id!r})."
        ),
    )


def _normalize_reference_target(
    raw: str,
    skill_id: str,
    *,
    local_target_ids: set[str],
    local_block_ids: set[str],
    reference_field: str,
) -> str:
    """Shared compile-time normalization for ``call:`` and ``link:`` targets."""
    if raw in local_block_ids:
        return format_ordered_block_target_id(skill_id, raw)

    block_prefix = f"{skill_id}{ORDERED_BLOCK_TARGET_ID_SEPARATOR}"
    if raw.startswith(block_prefix):
        block_id = raw[len(block_prefix) :]
        if block_id not in local_block_ids:
            raise _unknown_ordered_block_target_error(
                skill_id, block_id, reference_field=reference_field
            )
        return raw

    if raw in local_target_ids:
        return raw

    if ORDERED_BLOCK_TARGET_ID_SEPARATOR in raw:
        raise _cross_skill_target_error(raw, reference_field=reference_field)

    return raw


def _normalize_call_step(
    step: Step,
    skill_id: str,
    *,
    local_target_ids: set[str],
    local_block_ids: set[str],
) -> Step:
    """Return *step* with a normalized :class:`CallStep` target when applicable."""
    if not isinstance(step, CallStep):
        return step
    resolved_target = _normalize_reference_target(
        step.call,
        skill_id,
        local_target_ids=local_target_ids,
        local_block_ids=local_block_ids,
        reference_field="call",
    )
    if resolved_target == step.call:
        return step
    return step.model_copy(update={"call": resolved_target})


def _normalize_link_step(
    step: Step,
    skill_id: str,
    *,
    local_target_ids: set[str],
    local_block_ids: set[str],
) -> Step:
    """Return *step* with a normalized :class:`LinkStep` target when applicable."""
    if not isinstance(step, LinkStep):
        return step
    resolved_target = _normalize_reference_target(
        step.link,
        skill_id,
        local_target_ids=local_target_ids,
        local_block_ids=local_block_ids,
        reference_field="link",
    )
    if resolved_target == step.link:
        return step
    return step.model_copy(update={"link": resolved_target})


def _is_excluded_from_routable_entries(skill: Skill) -> bool:
    """Return whether *skill* must be omitted from `SkillCatalog.routable_entries`."""
    return skill.disabled or skill.hidden


def routable_target_id_for_skill(skill: Skill) -> str | None:
    """Return the skill id when the router may start *skill*.

    ``None`` when the skill has no single entry. A blocks-only skill is
    startable only when it has exactly one entry block. The id is always the
    skill id, not that block.
    """
    if entry_target_id_for_skill(skill) is None:
        return None
    return format_skill_target_id(skill.id)


def _is_intra_skill_block_target(
    skill_id: str, target: str, local_target_ids: set[str]
) -> bool:
    """Return whether *target* is an ordered block on *skill_id*."""
    if is_ordered_block_target_id(skill_id, target):
        return True
    return target in local_target_ids and target != skill_id


def merge_referenced_ids(*sources: list[str]) -> list[str]:
    """Merge referenced-target lists, deduplicating while preserving order."""
    seen: set[str] = set()
    merged: list[str] = []
    for source in sources:
        for target in source:
            if target in seen:
                continue
            seen.add(target)
            merged.append(target)
    return merged


# ---------------------------------------------------------------------------
# YAML loading helpers
# ---------------------------------------------------------------------------


def _load_yaml(path: Path) -> dict[str, Any]:
    """Load a YAML file and return its contents as a dict (empty dict if blank)."""
    with path.open(encoding="utf-8") as fh:
        return yaml.safe_load(fh) or {}


def _load_skill_dir(skill_dir: Path) -> Skill:
    """Load a single skill from its directory.

    Requires ``skill.md``.  A co-located ``memory.yml`` is applied when present.
    """
    skill_md_file = skill_dir / "skill.md"
    memory_file = skill_dir / "memory.yml"
    if not skill_md_file.is_file():
        raise FileNotFoundError(f"Skill directory '{skill_dir}' must contain skill.md.")

    # Local import to avoid circular dependency (markdown_skill_compiler
    # imports this module).
    from rasa.mantle.skills.markdown_skill_compiler import (
        compile_markdown_skill,
    )

    skill = compile_markdown_skill(skill_md_file)
    if memory_file.exists():
        memory_raw = _load_yaml(memory_file)
        skill = skill.model_copy(
            update={"memory": SkillMemoryContract.model_validate(memory_raw)}
        )

    return skill


def _parse_ordered_block_steps(raw_steps: Any) -> list[Step]:
    """Parse an ordered block's ``steps`` list."""
    if not raw_steps:
        return []
    return [parse_step(step) for step in raw_steps]


def _parse_ordered_block_tools(raw_tools: Any) -> list[GatedTool]:
    """Parse an ordered block's ``tools`` list."""
    if not raw_tools:
        return []
    tools: list[GatedTool] = []
    for item in raw_tools:
        if isinstance(item, str):
            tools.append(GatedTool(name=item))
        else:
            tools.append(GatedTool.model_validate(item))
    return tools


def parse_ordered_block_dict(block_id: str, raw: dict[str, Any]) -> OrderedBlock:
    """Parse a raw ordered-block mapping into an :class:`OrderedBlock`."""
    if "description" in raw:
        raise ValidationError(
            code="skill.markdown.ordered_block_description_forbidden",
            event_info=(
                f"Ordered block '{block_id}' must not set 'description'. "
                "Remove it; the orchestrator routes on the skill description."
            ),
        )
    return OrderedBlock(
        block_id=block_id,
        steps=_parse_ordered_block_steps(raw.get("steps")),
        tools=_parse_ordered_block_tools(raw.get("tools")),
        complete_when=raw.get("complete_when"),
        routable=raw.get("routable", True),
    )


def resolve_ordered_block_step_targets(
    skill_id: str,
    blocks: list[OrderedBlock],
    *,
    has_prose_entry: bool = False,
) -> list[OrderedBlock]:
    """Normalize ``call:`` / ``link:`` targets on every ordered block's steps."""
    local_block_ids = {block.block_id for block in blocks}
    local_target_ids = {
        format_ordered_block_target_id(skill_id, block.block_id) for block in blocks
    }
    if has_prose_entry:
        local_target_ids.add(skill_id)
    resolved: list[OrderedBlock] = []
    for block in blocks:
        steps = [
            _normalize_call_step(
                step,
                skill_id,
                local_target_ids=local_target_ids,
                local_block_ids=local_block_ids,
            )
            for step in block.steps
        ]
        steps = [
            _normalize_link_step(
                step,
                skill_id,
                local_target_ids=local_target_ids,
                local_block_ids=local_block_ids,
            )
            for step in steps
        ]
        resolved.append(block.model_copy(update={"steps": steps}))
    return resolved


def partition_call_link_targets_from_ordered_blocks(
    skill_id: str, blocks: list[OrderedBlock]
) -> tuple[list[str], list[str]]:
    """Split resolved ``call:`` / ``link:`` targets into (skills, blocks)."""
    local_target_ids = {
        format_ordered_block_target_id(skill_id, block.block_id) for block in blocks
    }
    seen: set[str] = set()
    referenced_skills: list[str] = []
    referenced_blocks: list[str] = []
    for block in blocks:
        for step in block.steps:
            target: str | None = None
            if isinstance(step, CallStep):
                target = step.call
            elif isinstance(step, LinkStep):
                target = step.link
            if target is None or target in seen:
                continue
            seen.add(target)
            if _is_intra_skill_block_target(skill_id, target, local_target_ids):
                referenced_blocks.append(target)
            elif target != skill_id:
                referenced_skills.append(target)
    return referenced_skills, referenced_blocks


class DuplicateSkillId(NamedTuple):
    """Two skill directories in the same tree declaring the same skill id."""

    skill_id: str
    first_directory: str
    second_directory: str


class SkillCatalogLoadResult(BaseModel):
    """Outcome of one traversal over a skills directory.

    Bundles the loaded catalog with the problems encountered on the way, so
    validation can report load failures and id collisions without re-parsing
    the tree a second time.
    """

    model_config = ConfigDict(frozen=True)

    catalog: SkillCatalog = Field(default_factory=SkillCatalog)
    load_errors: list[tuple[str, str]] = Field(default_factory=list)
    """One ``(directory_name, error_message)`` per unloadable skill directory."""

    duplicate_ids: list[DuplicateSkillId] = Field(default_factory=list)
    """Directory pairs within the traversed tree that declare the same id.

    Only collisions *within* one tree are recorded — a project skill overriding
    a default skill with the same id is a supported, intentional mechanism.
    """


def _load_skills_from_dir(
    skills_dir: Path,
    base_skills: dict[str, Skill] | None = None,
    *,
    inherit_flags_from: dict[str, Skill] | None = None,
) -> SkillCatalogLoadResult:
    """Traverse *skills_dir* once, loading every skill and recording problems.

    Directories starting with ``_`` and non-directories are skipped. Skills
    that fail to parse are logged and skipped (recorded in ``load_errors``);
    when two directories declare the same id the later one wins (recorded in
    ``duplicate_ids``). *base_skills* seeds the merged catalog and is
    intentionally excluded from duplicate detection (overriding a base skill
    by id is how projects replace default skills).
    """
    merged: dict[str, Skill] = dict(base_skills) if base_skills else {}
    load_errors: list[tuple[str, str]] = []
    duplicate_ids: list[DuplicateSkillId] = []
    directory_by_skill_id: dict[str, str] = {}
    bundled_flags = (
        inherit_flags_from if inherit_flags_from is not None else base_skills
    )

    if skills_dir.is_dir():
        # Sorted for a deterministic traversal: on a duplicate id the later
        # directory wins, matching the runtime load order. Non-directories and
        # ``_``-prefixed dirs (private/scratch) are not skills and are skipped.
        for skill_dir in sorted(skills_dir.iterdir()):
            if not skill_dir.is_dir() or skill_dir.name.startswith("_"):
                continue
            try:
                skill = _load_skill_dir(skill_dir)
                skill = _inherit_bundled_default_flags(skill, skill_dir, bundled_flags)
            except Exception as error:
                structlogger.exception(
                    "mantle.skill_catalog.skill_load_failed",
                    skill_dir=str(skill_dir),
                )
                load_errors.append((skill_dir.name, str(error)))
                continue
            if skill.id in directory_by_skill_id:
                duplicate_ids.append(
                    DuplicateSkillId(
                        skill_id=skill.id,
                        first_directory=directory_by_skill_id[skill.id],
                        second_directory=skill_dir.name,
                    )
                )
            directory_by_skill_id[skill.id] = skill_dir.name
            merged[skill.id] = skill
            structlogger.debug(
                "mantle.skill_catalog.skill_loaded",
                skill_id=skill.id,
                skill_dir=str(skill_dir),
            )

    return SkillCatalogLoadResult(
        catalog=SkillCatalog(skills=merged),
        load_errors=load_errors,
        duplicate_ids=duplicate_ids,
    )


def _routing_declares_engine_managed(skill_dir: Path) -> bool:
    """Return whether the project skill explicitly sets ``routing.engine_managed``."""
    skill_md = skill_dir / "skill.md"
    if skill_md.is_file():
        from rasa.mantle.skills.markdown_skill_compiler import split_skill_markdown

        frontmatter, _ = split_skill_markdown(skill_md.read_text(encoding="utf-8"))
        routing = frontmatter.get("routing", {}) or {}
        if isinstance(routing, dict) and "engine_managed" in routing:
            return True

    return False


def _inherit_bundled_default_flags(
    skill: Skill,
    skill_dir: Path,
    bundled_skills: dict[str, Skill] | None,
) -> Skill:
    """Preserve bundled-default routing flags on project overrides.

    Project skills replace bundled defaults on duplicate IDs.  When the
    bundled skill was marked ``is_default`` or ``engine_managed`` and the
    project's ``skill.md`` omits the corresponding ``routing`` key, inherit
    the bundled flag so customized lifecycle defaults keep their runtime role.
    """
    if not bundled_skills:
        return skill
    bundled_default = bundled_skills.get(skill.id)
    if bundled_default is None:
        return skill

    updates: dict[str, bool] = {}
    if bundled_default.is_default:
        updates["is_default"] = True
    if bundled_default.engine_managed and not _routing_declares_engine_managed(
        skill_dir
    ):
        updates["engine_managed"] = True

    if not updates:
        return skill
    return skill.model_copy(update=updates)


def _raise_on_skill_load_errors(
    result: SkillCatalogLoadResult,
    *,
    skills_root_label: str,
) -> None:
    """Abort runtime skill loading on parse failures or duplicate skill ids.

    :func:`load_skill_catalog_result` / :func:`load_default_skill_catalog_result`
    still return ``load_errors`` and ``duplicate_ids`` for validation
    reporting. The plain catalog loaders used at agent startup must fail closed
    instead of silently skipping broken skills or picking a winner on id
    collisions within one skills tree.
    """
    if result.load_errors:
        details = "; ".join(
            f"'{directory}': {error}" for directory, error in result.load_errors
        )
        raise ValidationError(
            code="skill.catalog.load_failed",
            event_info=(
                f"Failed to load skill(s) under {skills_root_label}: {details}. "
                "Fix the skill(s) so they parse, or remove them."
            ),
        )

    if result.duplicate_ids:
        details = "; ".join(
            f"'{duplicate.first_directory}' and "
            f"'{duplicate.second_directory}' both declare skill id "
            f"{duplicate.skill_id!r}"
            for duplicate in result.duplicate_ids
        )
        raise ValidationError(
            code="skill.catalog.duplicate_id",
            event_info=(
                f"Duplicate skill id(s) under {skills_root_label}: {details}. "
                "Each skill must have a unique directory name."
            ),
        )


def load_default_skill_catalog_result() -> SkillCatalogLoadResult:
    """Load the bundled default skills, keeping load problems.

    Like :func:`load_default_skill_catalog`, but returns the full
    :class:`SkillCatalogLoadResult` so validation can report bundled skills
    that failed to parse without aborting.
    """
    default_skills_dir = Path(__file__).parent.parent / "default_skills"
    result = _load_skills_from_dir(default_skills_dir)
    marked_skills = {
        skill_id: skill.model_copy(update={"is_default": True})
        for skill_id, skill in result.catalog.skills.items()
    }
    return result.model_copy(update={"catalog": SkillCatalog(skills=marked_skills)})


def load_default_skill_catalog() -> SkillCatalog:
    """Load the built-in default skills bundled with the rasa package.

    Default skills live under ``rasa/mantle/default_skills/<skill_id>/``.
    Every skill loaded from that directory is marked ``is_default=True`` by
    this function regardless of frontmatter content (``is_default`` is
    intentionally not authorable in ``skill.md``).

    Returns:
        A :class:`SkillCatalog` containing all built-in default skills.

    Raises:
        ValidationError: When any bundled default skill directory fails to parse
            or when two directories declare the same skill id.
    """
    result = load_default_skill_catalog_result()
    _raise_on_skill_load_errors(result, skills_root_label="bundled default_skills")
    return result.catalog


def load_skill_catalog_result(
    snapshot_dir: Path,
    defaults: SkillCatalog | None = None,
    *,
    inherit_flags_from: dict[str, Skill] | None = None,
) -> SkillCatalogLoadResult:
    """Load ``<snapshot_dir>/skills/`` in one pass, keeping load problems.

    Like :func:`load_skill_catalog`, but returns the full
    :class:`SkillCatalogLoadResult` so validation can report unloadable skill
    directories and duplicate skill ids without re-parsing the tree (and without
    aborting on the first load error).

    Args:
        snapshot_dir: Path to the extracted model snapshot directory. Skills
            are expected under ``<snapshot_dir>/skills/<skill_id>/``.
        defaults: A pre-loaded defaults catalog (e.g. from
            ``load_default_skill_catalog()``).  Project skills override
            defaults on duplicate IDs; such overrides are *not* recorded as
            duplicates.
        inherit_flags_from: Optional bundled skills used only to inherit
            ``is_default`` / ``engine_managed`` on project overrides without
            merging those skills into the returned catalog.

    Returns:
        The merged catalog plus the load errors and duplicate ids encountered.
    """
    if inherit_flags_from is not None:
        bundled_for_flags: Optional[dict[str, Skill]] = inherit_flags_from
    else:
        bundled_for_flags = defaults.skills if defaults is not None else None

    return _load_skills_from_dir(
        snapshot_dir / "skills",
        base_skills=defaults.skills if defaults is not None else None,
        inherit_flags_from=bundled_for_flags,
    )


def load_skill_catalog(
    snapshot_dir: Path,
    defaults: SkillCatalog | None = None,
) -> SkillCatalog:
    """Load all skills from ``<snapshot_dir>/skills/`` and merge with *defaults*.

    Args:
        snapshot_dir: Path to the extracted model snapshot directory. Skills
            are expected under ``<snapshot_dir>/skills/<skill_id>/``.
        defaults: A pre-loaded defaults catalog (e.g. from
            ``load_default_skill_catalog()``).  Project skills override
            defaults on duplicate IDs.

    Returns:
        A :class:`SkillCatalog` with all skills merged.

    Raises:
        ValidationError: When any project skill directory under
            ``<snapshot_dir>/skills/`` fails to parse, or when two project
            skill directories declare the same skill id.
    """
    result = load_skill_catalog_result(snapshot_dir, defaults=defaults)
    _raise_on_skill_load_errors(result, skills_root_label=str(snapshot_dir / "skills"))
    return result.catalog
